command:
// 1. QS holen
const qsWert = Number(testData.result?.QL || testData.qualityStep || 0);
const symbolPfad = "https://assets.forge-vtt.com/644fbc20a9e089e2ef894956/modules/dsk-core/icons/journal/image-440.webp";
const infoBildPfad = "https://assets.forge-vtt.com/644fbc20a9e089e2ef894956/DSK/Allgemein/system-dsk-info2.webp";
const akteurName = actor.name;

if (qsWert > 0) {
    const zielToken = game.user.targets.first();
    const zielActor = zielToken?.actor;

    if (zielActor) {
        const maxSchips = zielActor.system.stats.schips.max || 0;
        const schipsAbzug = Math.round(qsWert / 2);

        if (maxSchips > 0) {
            // Effekt erstellen
            const effektDaten = {
                name: "Schwarze Katze",
                icon: symbolPfad,
                duration: { rounds: null, startTime: game.time.worldTime },
                changes: [
                    { key: "system.stats.schips.gearmodifier", mode: 2, value: -schipsAbzug },
                    { key: "system.stats.at.gearmodifier", mode: 2, value: -1 } 
                ]
            };
            await zielActor.createEmbeddedDocuments("ActiveEffect", [effektDaten]);

            ChatMessage.create({
                content: `
                <div style="font-family: 'Signika', sans-serif;">
                    <div style="background: linear-gradient(90deg, rgba(25, 20, 55, 0.95) 0%, rgba(45, 35, 90, 0.6) 50%, rgba(45, 35, 90, 0.1) 100%); color: #ffffff; font-weight: bold; padding: 8px 12px; border-radius: 4px; display: flex; align-items: center; justify-content: space-between; border: 1px solid #777;">
                        <span>⚙️ Aphasma-Gabe</span>
                        <img src="${symbolPfad}" style="width: 24px; height: 24px; border: none;">
                    </div>
                    <div style="text-align: center; font-weight: bold; margin: 8px 0; border-bottom: 1px solid #ccc; padding-bottom: 4px;">
                        Aktiver Effekt: Schwarze Katze
                    </div>
                    <div style="display: flex; align-items: flex-start; gap: 10px; margin-top: 5px;">
                        <img src="${infoBildPfad}" style="width: 80px; height: auto; border-radius: 4px; border: none;">
                        <div style="line-height: 1.4; font-size: 0.95em;">
                            🐈‍⬛ <b>${akteurName}</b> hat <b>${zielToken.name}</b> heimgesucht.<br>
                            Verlust: <b>${schipsAbzug} Schicksalspunkt(e)</b> und <b>1 Aktiver Punkt</b>.<br>
                            ⏳ <b>Dauer:</b> Bis zur nächsten langen Rast.
                        </div>
                    </div>
                </div>`,
                speaker: ChatMessage.getSpeaker({ actor: actor })
            });
        } else {
            // Rote Box für Fehlgeschlagen
            ChatMessage.create({
                content: `
                <div style="font-family: 'Signika', sans-serif;">
                    <div style="background: #8b0000; color: white; font-weight: bold; padding: 8px; border-radius: 4px; display: flex; align-items: center; justify-content: space-between; border: 1px solid #777;">
                        <span>⚙️ Ahnengabe misslungen</span>
                        <img src="${symbolPfad}" style="width: 24px; height: 24px; border: none;">
                    </div>
                    <div style="margin-top: 8px;">
                        ${zielToken.name} besitzt keine Schicksalspunkte.
                    </div>
                </div>`,
                speaker: ChatMessage.getSpeaker({ actor: actor })
            });
        }
    } else {
        ui.notifications.warn("Bitte wähle ein Ziel-Token aus.");
    }
}
